<template><div class="page-shell"><div class="page-title-row"><div><h1 class="page-title">风险规则配置</h1><p class="page-subtitle">以配置化阈值识别库存不足、仓储异常、道路阻断与气象灾害，避免将判断逻辑写死在程序中</p></div><el-alert title="规则修改后将在下一次风险扫描中生效" type="success" :closable="false" show-icon/></div><CrudManager title="预警规则" endpoint="/rules" :columns="columns" :fields="fields" :can-create="auth.isAdmin" :can-edit="auth.isAdmin" :can-delete="auth.isAdmin" :defaults="{riskType:'INVENTORY',metric:'availableStock',operator:'LT',alarmLevel:'HIGH',enabled:true}"/></div></template>
<script setup>
import CrudManager from '../components/CrudManager.vue';import { useAuthStore } from '../stores/auth';const auth=useAuthStore();const opt=o=>Object.entries(o).map(([value,label])=>({value,label}));
const types=opt({INVENTORY:'库存风险',TEMPERATURE:'温度异常',HUMIDITY:'湿度异常',TRAFFIC:'交通阻断',WEATHER:'气象灾害',REGIONAL_SUPPLY:'区域供应'}),levels=opt({LOW:'低',MEDIUM:'中',HIGH:'高',CRITICAL:'紧急'}),operators=opt({LT:'小于',LE:'小于等于',GT:'大于',GE:'大于等于',EQ:'等于',CONTAINS:'包含'});
const columns=[{prop:'name',label:'规则名称',width:190},{prop:'riskType',label:'风险类型',formatter:v=>Object.fromEntries(types.map(x=>[x.value,x.label]))[v]||v},{prop:'metric',label:'指标字段'},{prop:'operator',label:'运算符'},{prop:'thresholdValue',label:'数值阈值'},{prop:'thresholdText',label:'文本阈值'},{prop:'alarmLevel',label:'告警等级',tag:true},{prop:'suggestion',label:'处理建议',width:260},{prop:'enabled',label:'状态',tag:true}];
const fields=[{prop:'name',label:'规则名称',required:true},{prop:'riskType',label:'风险类型',type:'select',options:types,required:true},{prop:'metric',label:'指标字段',required:true},{prop:'operator',label:'运算符',type:'select',options:operators,required:true},{prop:'thresholdValue',label:'数值阈值',type:'number'},{prop:'thresholdText',label:'文本阈值'},{prop:'alarmLevel',label:'告警等级',type:'select',options:levels,required:true},{prop:'suggestion',label:'处理建议',type:'textarea',wide:true,required:true},{prop:'enabled',label:'是否启用',type:'switch'}];
</script>
